SRC = """// 示例被测源码：行号从 1 开始
int add(int a, int b) {
    return a + b;
}

int div_int(int a, int b) {
    if (b == 0) return -1;
    return a / b;
}

int max3(int a, int b, int c) {
    int m = a > b ? a : b;
    return m > c ? m : c;
}
"""

SKIP = ("{", "}", "};", ");")


def executable_lines(text):
    out = []
    for no, raw in enumerate(text.splitlines(), 1):
        s = raw.strip()
        if not s:
            continue
        if s.startswith(("//", "/*", "*", "#")):
            continue
        if s in SKIP:
            continue
        out.append(no)
    return out


def coverage(execd, text):
    lv = executable_lines(text)
    hit = [n for n in lv if n in execd]
    miss = [n for n in lv if n not in execd]
    pct = round(100.0 * len(hit) / len(lv), 1)
    return pct, len(hit), len(lv), miss


A = {1, 2, 5, 6, 7}                                   # 只测 add 与 div 的正常路径
B = {1, 2, 5, 6, 7, 10, 11, 12}                       # 补上 b==0 分支与 max3

lv = executable_lines(SRC)
print("[源码] 总行=%d 注释与空行=%d 可执行行=%d" % (len(SRC.splitlines()), len(SRC.splitlines()) - len(lv), len(lv)))
print("[可执行行号] %s" % lv)
for name, execd in (("测试A", A), ("测试B", B)):
    pct, hit, tot, miss = coverage(execd, SRC)
    print("[%s] 覆盖=%d/%d 行覆盖率=%s%% 未覆盖行=%s" % (name, hit, tot, pct, miss))
pa, _, _, _ = coverage(A, SRC)
pb, _, _, _ = coverage(B, SRC)
print("[门槛 80%%] 测试A=%s 测试B=%s" % (pa >= 80.0, pb >= 80.0))
print("[判定] 同一份源码换一套用例，覆盖率从 %s%% 提升到 %s%% -> 覆盖率是「用例质量」的镜像" % (pa, pb))
